(* [comment removed for export] *)
Ltac wseed H l h :=
  let go A2 s2 := (let W := fresh "WS" in assert (W : hideL (A2 + s2 <= l \/ h <= A2)); [unfold hideL|]) in
  lazymatch type of H with
  | rw_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  | ro_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
  end.
(* [comment removed for export] *)
Ltac in_seed MU T :=
  lazymatch type of MU with munch ?W _ _ => lazymatch type of T with rw_cells _ _ ?A ?cs =>
    let S := dj_size_cells cs in let K := fresh "INs" in assert (K : chunk_in W A S); [unfold chunk_in; cbn [inside fst snd]|] end end.
Ltac in_noseed MU T :=
  lazymatch type of MU with munch ?W _ _ => lazymatch type of T with rw_cells _ _ ?A ?cs =>
    let S := dj_size_cells cs in let K := fresh "INn" in pose proof (I : chunk_noin W A S) as K end end.






