Lemma spc_hdr_fold' : forall m q vp u w i j7,
  rw_cells bsegs m q [C8 (Z_to_bv 64 vp); C4 (Z_to_bv 64 u); C4 (Z_to_bv 64 w); C8 (Z_to_bv 64 0); C1 (Z_to_bv 8 i); CB 7 j7] ->
  rw_cells bsegs m q (SpcHdrCells (mkSPC vp u w i) j7).
Proof.
  intros m q vp u w i j7 RC. pose proof RC as [[WF _] _]. cbn in WF.
  eapply rw_cells_reshape; [exact RC| cbn; repeat split; lia| reflexivity].
Qed.

