Ltac mss_bundle_now HH RFc ACc SK2 FF MU3 WM3 W3K RFx ACx SKx :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    lazymatch type of SK2 with stack0 _ ?lo ?shi => lazymatch type of RFc with as_RFS ?H ?LFc _ =>
    let B := fresh "BND" in
    assert (B : as_RFS H LFc mc /\ ACONST mc /\ stack0 mc lo shi)
      by (eapply (fs_frame_writes_pl _ HH); [exact RFc| exact ACc| exact SK2| exact FF| exact MU3| exact WM3| exact W3K]);
    destruct B as (RFx & ACx & SKx) end end end.
Ltac mss_acc_now AC MU3 WFR F1 F3 SEP ACn :=
  lazymatch type of AC with accessible _ ?O ?n =>
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    assert (ACn : accessible mc O n)
      by (eapply (accessible_transport_fr _ _ mc O n _ 16); [exact AC| exact MU3| exact WFR| clear - F1; lia| exact F3| clear; lia| clear - SEP; unhideL; lia])
  end end.

(* [comment removed for export] *)
Lemma mss_segB : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' xs6 xs7 : word)
    (R EX SPP FCP q implb ioc spa lo shi ff fp : Z) (ivp iu ii : Z) (p : bptr) (LB' : list block) (LF : list fframe)
    (m m0 : mem) (lowpad high : list cell) (ja h32 e48 e8 r32 j7 junk jr j16 ij7 : list byte) (z0 z1 z2 z3 z11 z12 z13 z14 z15 : byte),
  (pcv = Z_to_bv 64 AMSS_RET1 \/ pcv = ret_pc (Z_to_bv 64 AMSS_RET1)) ->
  rw_cells bsegs m spa lowpad -> Z.of_nat (cells_size lowpad) = 8 -> lo + AINTRIN_STACK <= spa -> spa + 160 <= bv_unsigned sp -> spa mod 16 = 0 ->
  rw_cells bsegs m (spa + 8) [CB 24 ja; C8 (Z_to_bv 64 ff); C8 (Z_to_bv 64 0)] ->
  rw_cells bsegs m (spa + 48) [C8 (Z_to_bv 64 q)] ->
  rw_cells bsegs m (spa + 56) high -> Z.of_nat (cells_size high) = bv_unsigned sp + -160 - spa ->
  rw_cells bsegs m (bv_unsigned sp + -104) (mss_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs m ff [CB 32 h32; CB 48 e48; CB 8 e8; CB 32 r32; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880)
     [C1 z0; C1 z1; C1 z2; C1 z3; C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 z11; C1 z12; C1 z13; C1 z14; C1 z15] ->
  rw_cells bsegs m fp [C1 (b8 1)] ->
  stk bsegs m lo spa -> mem_inv bsegs m ->
  as_RFS H ((1, ff, fp) :: LF) m -> fresh_frame H LF 1 ff fp -> ACONST m -> stack0 m lo shi -> bv_unsigned sp + 64 <= shi ->
  as_RFS H LF m0 ->
  (* [comment removed for export] *)
  rw_cells bsegs m q (SpcHdrCells (mkSPC AVP_SPCI_STATE 1 1 0) j7) -> rw_cells bsegs m (q + 32) [CB 280 junk] ->
  rblock_range q 312 -> addressable m q 312 -> shvis m (q + 32) (q + 312) -> In (p, q, 312) LB' -> fsobj H LF q 312 ->
  (* [comment removed for export] *)
  rw_cells bsegs m R [CB 16 jr] -> aplace R 16 -> (R + 16 <= lo \/ bv_unsigned sp <= R) -> R mod 8 = 0 -> accessible m R 16 -> fsobj H LF R 16 -> (R + 16 <= q \/ q + 312 <= R) ->
  ro_cells bsegs m EX (AnyExecCells EX ioc j16) -> aapp EX 56 -> EX mod 8 = 0 -> accessible m EX 56 -> 0 < EX -> 0 <= ioc < 2^64 -> fsobj H LF EX 56 ->
  (R + 16 <= EX \/ EX + 56 <= R) ->
  ro_cells bsegs m SPP [C8 (wz (implb + 32)); C8 (wz implb)] -> aapp SPP 16 -> SPP mod 8 = 0 -> accessible m SPP 16 -> fsobj H LF SPP 16 ->
